function isTraceLine(r: number, g: number, b: number, traceColors: { red: boolean; blue: boolean; green: boolean }): boolean {
  if (traceColors.red && r > 180 && g < 100 && b < 100) return true;
  if (traceColors.blue && b > 180 && r < 100 && g < 100) return true;
  if (traceColors.green && g > 180 && r < 100 && b < 100) return true;
  return false;
}

// ピクセルが塗りつぶし境界（壁）であるかを判定
function isBoundary(
  data: Uint8ClampedArray,
  idx: number,
  targetR: number,
  targetG: number,
  targetB: number,
  options: ToolOptions
): boolean {
  const r = data[idx];
  const g = data[idx + 1];
  const b = data[idx + 2];
  const a = data[idx + 3];

  if (a === 0) return false;

  if (options.enableIncludeTrace && isTraceLine(r, g, b, options.traceColors)) {
    return true; // 色トレス線は壁として扱う
  }

  const diff = Math.abs(r - targetR) + Math.abs(g - targetG) + Math.abs(b - targetB);
  return diff > options.tolerance * 3;
}

// 1. バケツ塗り (Flood Fill)
export function floodFill(
  data: Uint8ClampedArray,
  width: number,
  height: number,
  startX: number,
  startY: number,
  fillColor: RGBAColor,
  options: ToolOptions
): void {
  if (startX < 0 || startX >= width || startY < 0 || startY >= height) return;

  const startIdx = (startY * width + startX) * 4;
  const targetR = data[startIdx];
  const targetG = data[startIdx + 1];
  const targetB = data[startIdx + 2];
  const targetA = data[startIdx + 3];

  if (
    targetR === fillColor.r &&
    targetG === fillColor.g &&
    targetB === fillColor.b &&
    targetA === fillColor.a
  ) {
    return;
  }

  const visited = new Uint8Array(width * height);
  const queue: number[] = [startX, startY];
  visited[startY * width + startX] = 1;

  const filledIndices: number[] = [];

  while (queue.length > 0) {
    const y = queue.pop()!;
    const x = queue.pop()!;
