runPegStabilizerAutoDetect: () => {
  const { currentImage, triggerRender } = get();
  if (!currentImage) return;

  const res = detectPegHolesAndCalculateTransform(
    currentImage.data,
    currentImage.width,
    currentImage.height
  );

  set((state) => ({
    pegStabilizer: {
      ...state.pegStabilizer,
      enabled: true,
      status: res.status,
      offsetX: res.offsetX,
      offsetY: res.offsetY,
      rotation: res.rotation,
    },
  }));
  triggerRender();
},

