import { floodFill, sampleColorAt, ToolOptions } from '../../../../Users/inouemacmini/Desktop/Kingfisher/src/engine/paintAlgorithm';

const W = 60;
const H = 40;

function newCanvas(): Uint8ClampedArray {
  const d = new Uint8ClampedArray(W * H * 4);
  for (let i = 0; i < d.length; i += 4) {
    d[i] = 255; d[i + 1] = 255; d[i + 2] = 255; d[i + 3] = 0; // 純白=透明
  }
  return d;
}

function setPx(d: Uint8ClampedArray, x: number, y: number, r: number, g: number, b: number, a: number) {
  const i = (y * W + x) * 4;
  d[i] = r; d[i + 1] = g; d[i + 2] = b; d[i + 3] = a;
}

function getPx(d: Uint8ClampedArray, x: number, y: number) {
  const i = (y * W + x) * 4;
  return { r: d[i], g: d[i + 1], b: d[i + 2], a: d[i + 3] };
}

// (5,5)-(30,30) の黒枠。gapAtTop>0 なら上辺の中央に隙間を空ける
function drawBox(d: Uint8ClampedArray, gapAtTop = 0) {
  const x0 = 5, x1 = 30, y0 = 5, y1 = 30;
  const gapStart = 17;
  for (let x = x0; x <= x1; x++) {
    const inGap = gapAtTop > 0 && x >= gapStart && x < gapStart + gapAtTop;
    if (!inGap) setPx(d, x, y0, 0, 0, 0, 255);
    setPx(d, x, y1, 0, 0, 0, 255);
  }
  for (let y = y0; y <= y1; y++) {
    setPx(d, x0, y, 0, 0, 0, 255);
    setPx(d, x1, y, 0, 0, 0, 255);
  }
}

function countFilled(d: Uint8ClampedArray, color: { r: number; g: number; b: number }) {
  let n = 0;
  for (let i = 0; i < d.length; i += 4) {
    if (d[i] === color.r && d[i + 1] === color.g && d[i + 2] === color.b && d[i + 3] === 255) n++;
  }
  return n;
}

const baseOptions: ToolOptions = {
  gapCloseLevel: 0,
  enableIncludeTrace: false,
  retainTraceLine: false,
  traceColors: { red: false, blue: false, green: false },
  tolerance: 0,
  brushSize: 5,
  expandContract: 0,
  contiguous: true,
  sampleSize: '1x1',
  referenceLayer: 'current',
};

const YELLOW = { r: 255, g: 255, b: 0, a: 255 };
let pass = 0;
let fail = 0;

function check(name: string, cond: boolean, detail = '') {
  if (cond) { pass++; console.log(`  ✅ ${name}`); }
  else { fail++; console.log(`  ❌ ${name}  ${detail}`); }
}

console.log('\n--- 1. 基本のバケツ塗り (閉じた領域) ---');
{
  const d = newCanvas();
  drawBox(d);
  floodFill(d, W, H, 15, 15, YELLOW, baseOptions);
  const inside = getPx(d, 15, 15);
  const outside = getPx(d, 50, 35);
  check('内側が塗られる', inside.r === 255 && inside.g === 255 && inside.b === 0 && inside.a === 255);
  check('外側は塗られない', outside.a === 0, JSON.stringify(outside));
  check('塗り面積は枠内 (24x24=576)', countFilled(d, YELLOW) === 576, `= ${countFilled(d, YELLOW)}`);
}

console.log('\n--- 2. 隙間閉じ OFF: 3px の切れ目から液漏れする (現状再現) ---');
let leakCount = 0;
{
  const d = newCanvas();
  drawBox(d, 3);
  floodFill(d, W, H, 15, 15, YELLOW, baseOptions);
  leakCount = countFilled(d, YELLOW);
  const outside = getPx(d, 50, 35);
  check('OFF のとき外側まで漏れる', outside.a === 255, JSON.stringify(outside));
  console.log(`     (塗られた画素数: ${leakCount})`);
}

console.log('\n--- 3. 隙間閉じ ON (gapCloseLevel=6): 液漏れが止まる ---');
{
  const d = newCanvas();
  drawBox(d, 3);
  floodFill(d, W, H, 15, 15, YELLOW, { ...baseOptions, gapCloseLevel: 6 });
  const inside = getPx(d, 15, 15);
  const outside = getPx(d, 50, 35);
  const n = countFilled(d, YELLOW);
  check('内側は塗られる', inside.r === 255 && inside.g === 255 && inside.b === 0);
  check('外側へ漏れない', outside.a === 0, JSON.stringify(outside));
  check('塗り面積が漏れ時より大幅に小さい', n < leakCount / 2, `n=${n}, leak=${leakCount}`);
  console.log(`     (塗られた画素数: ${n} / 漏れた場合は ${leakCount})`);
}

console.log('\n--- 4. 隙間閉じ ON でも、隙間より大きい開口部は塗り抜ける ---');
{
  const d = newCanvas();
  drawBox(d, 10); // 10px の大穴
  floodFill(d, W, H, 15, 15, YELLOW, { ...baseOptions, gapCloseLevel: 6 });
  const outside = getPx(d, 50, 35);
  check('gapCloseLevel(6) より広い 10px の開口は通す', outside.a === 255, JSON.stringify(outside));
