  drawBox(d, 3);
  floodFill(d, W, H, 15, 15, YELLOW, { ...baseOptions, gapCloseLevel: 6 });
  const inside = getPx(d, 15, 15);
  const outside = getPx(d, 50, 35);
  const n = countFilled(d, YELLOW);
  check('内側は塗られる', inside.r === 255 && inside.g === 255 && inside.b === 0);
  check('外側へ漏れない', outside.a === 0, JSON.stringify(outside));
  check('塗り面積が漏れ時より大幅に小さい', n < leakCount / 2, `n=${n}, leak=${leakCount}`);
  console.log(`     (塗られた画素数: ${n} / 漏れた場合は ${leakCount})`);
}

