import React, { useRef, useEffect, useState, useCallback } from 'react';
import { usePaintStore } from '../../store/usePaintStore';
import { floodFill, gradientFill, closedAreaFill, drawBrushLine, removeSingleNoiseAt, sampleColorAt } from '../../engine/paintAlgorithm';
