  it('履歴は積まれない', () => {
    s().saveUndoState('無効な操作');
    expect(s().historyStack.length).toBe(0);
  });

  it('undo / redo / jumpToHistory が例外を投げない', () => {
    expect(() => {
      s().undo();
      s().redo();
      s().jumpToHistory(0);
      s().commitLiveState();
    }).not.toThrow();
  });
});

