import React from 'react';
import { Minimize2, MoveUpRight } from 'lucide-react';

interface DockPlaceholderProps {
  /** ドッキング復帰のドロップ判定に使う id。useFloatingWindow の dockTargetId と揃える */
  id: string;
  /** 「Win A」など、どのウィンドウの跡地かを示す名前 */
  label: string;
  /** ドッキングへ戻す */
  onRestore: () => void;
  /** ドラッグ中のウィンドウがこの領域の上にいるか */
  isActive?: boolean;
  /** full: 空いた領域全体を占める / strip: 細い帯だけを残す */
  variant?: 'full' | 'strip';
}

/**
 * 独立ウィンドウとして切り離されたパネルの「跡地」。
 *
 * 2つの役割がある:
 *  1. ドラッグでドッキングへ戻すためのドロップ先 (実際に表示されている必要がある)
 *  2. ウィンドウを画面の外や他ウィンドウの裏で見失った時の復帰導線
 */
export const DockPlaceholder: React.FC<DockPlaceholderProps> = ({
  id,
  label,
  onRestore,
  isActive = false,
  variant = 'full',
}) => {
  const activeRing = isActive
    ? 'border-blue-500 bg-blue-500/10 ring-2 ring-blue-500/40'
    : 'border-slate-400/60 dark:border-slate-600/60 hover:border-blue-400 hover:bg-blue-500/5';

  if (variant === 'strip') {
    return (
      <div
        id={id}
        onClick={onRestore}
        title={`${label} をドッキング表示に戻す`}
        className={`w-11 flex-shrink-0 flex flex-col items-center justify-center gap-2 border-2 border-dashed rounded cursor-pointer transition-colors select-none ${activeRing}`}
      >
        <MoveUpRight className="w-3.5 h-3.5 text-slate-500 dark:text-slate-400 flex-shrink-0" />
        <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 [writing-mode:vertical-rl] tracking-wider">
          {label} は独立表示中
        </span>
        <Minimize2 className="w-3.5 h-3.5 text-blue-600 dark:text-blue-400 flex-shrink-0" />
      </div>
    );
  }

  return (
    <div
      id={id}
      className={`flex-1 min-w-[120px] flex flex-col items-center justify-center gap-3 border-2 border-dashed rounded transition-colors select-none p-4 ${activeRing}`}
    >
      <MoveUpRight className="w-6 h-6 text-slate-400 dark:text-slate-500" />
      <div className="text-center">
        <p className="text-xs font-bold text-slate-600 dark:text-slate-300">
          {label} は独立ウィンドウで表示中
        </p>
        <p className="text-[10px] text-slate-500 dark:text-slate-400 mt-1">
          タイトルバーをここへドロップすると元に戻ります
        </p>
      </div>
      <button
        onClick={onRestore}
        className="px-2.5 py-1 rounded text-[11px] font-bold flex items-center gap-1.5 bg-blue-600 hover:bg-blue-700 text-white shadow-xs transition-colors"
      >
        <Minimize2 className="w-3 h-3" />
        ここに戻す
      </button>
    </div>
  );
};

