1	import React, { useCallback, useRef, useState } from 'react';
2	import { usePaintStore } from '../store/usePaintStore';
3	import { FloatingWindowId } from '../store/types';
4	import { useFastDraggable } from './useFastDraggable';
5	import { useResizableWindow } from './useResizableWindow';
6	
7	/**
8	 * 独立ウィンドウ (フローティング) の共通処理。
9	 *
10	 * これまで Win A / Win B・参照ウィンドウ・カラーチャートで実装が三者三様に分かれ、
11	 * 「引きはがせるがドラッグでは戻せない」「戻すとズレる」といった差異を生んでいた。
12	 * 位置・サイズ・重なり順はストアが持ち、ここが唯一の操作窓口になる。
13	 *
14	 * ドッキング復帰の判定には「実際に画面に出ている領域」だけを使う。
15	 * 非表示要素は getBoundingClientRect() が 0 を返し、画面左上の隅が
16	 * ドロップ領域になってしまうため、大きさを持つことを必須条件にしている。
17	 */
18	
19	/** 引きはがしと判定するドラッグ距離 (px) */
20	const TEAR_OFF_THRESHOLD = 6;
21	
22	/** ドッキング領域の判定に持たせる余白 (px) */
23	const DOCK_HIT_PADDING = 24;
24	
25	function getVisibleRect(elementId: string): DOMRect | null {
26	  const el = document.getElementById(elementId);
27	  if (!el || el.offsetParent === null) return null;
28	  const rect = el.getBoundingClientRect();
29	  if (rect.width <= 0 || rect.height <= 0) return null;
30	  return rect;
31	}
32	
33	function isPointerOverRect(rect: DOMRect, clientX: number, clientY: number): boolean {
34	  return (
35	    clientX >= rect.left - DOCK_HIT_PADDING &&
36	    clientX <= rect.right + DOCK_HIT_PADDING &&
37	    clientY >= rect.top - DOCK_HIT_PADDING &&
38	    clientY <= rect.bottom + DOCK_HIT_PADDING
39	  );
40	}
41	
42	interface UseFloatingWindowOptions {
43	  id: FloatingWindowId;
44	  /** 現在フローティングかどうか (描画用) */
45	  isFloating: boolean;
46	  /** ドラッグ中に最新値を読むための関数。React のクロージャは古い値を掴むため必要 */
47	  getIsFloating: () => boolean;
48	  toggleFloating: () => void;
49	  /** ドッキング復帰のドロップ先となる要素の id */
50	  dockTargetId: string;
51	  minWidth?: number;
52	  minHeight?: number;
53	  /** 中身がはみ出す時の扱い。スクロールさせたいパネルは 'auto' */
54	  contentOverflow?: 'hidden' | 'auto';
55	}
56	
57	export function useFloatingWindow<T extends HTMLElement = HTMLDivElement>({
58	  id,
59	  isFloating,
60	  getIsFloating,
61	  toggleFloating,
62	  dockTargetId,
63	  minWidth = 240,
64	  minHeight = 180,
65	  contentOverflow = 'hidden',
66	}: UseFloatingWindowOptions) {
67	  const layout = usePaintStore((s) => s.floatingWindows[id]);
68	  const order = usePaintStore((s) => s.floatingWindowOrder);
69	  const setFloatingWindowPosition = usePaintStore((s) => s.setFloatingWindowPosition);
70	  const setFloatingWindowSize = usePaintStore((s) => s.setFloatingWindowSize);
71	  const bringWindowToFront = usePaintStore((s) => s.bringWindowToFront);
72	
73	  /** ドッキング領域の上にいるか (復帰ガイドの表示に使う) */
74	  const [isOverDockTarget, setIsOverDockTarget] = useState(false);
75	
76	  const { targetRef, currentPos, setPosition } = useFastDraggable<T>({
77	    initialX: layout.x,
78	    initialY: layout.y,
79	    enabled: isFloating,
80	    onCommit: (x, y) => setFloatingWindowPosition(id, x, y),
81	  });
82	
83	  const { getResizeHandler } = useResizableWindow(targetRef, currentPos, setPosition, {
84	    minWidth,
85	    minHeight,
86	    enabled: isFloating,
87	    onCommit: (w, h) => setFloatingWindowSize(id, w, h),
88	  });
89	
90	  const isDraggingHeader = useRef(false);
91	  const dragOffset = useRef({ x: 0, y: 0 });
92	
93	  /** タイトルバーの掴み込み: ドッキング中なら引きはがし、独立中なら移動＋復帰判定 */
94	  const handleHeaderPointerDown = useCallback(
95	    (e: React.PointerEvent) => {
96	      if (e.button !== 0) return;
97	      e.stopPropagation();
98	
99	      bringWindowToFront(id);
100	      isDraggingHeader.current = true;
101	
102	      const startX = e.clientX;
103	      const startY = e.clientY;
104	
105	      // 掴んだ相対位置をそのまま保つ。
106	      // ドッキング中のパネルは独立時より横に広いことがあるので、
107	      // カーソルがウィンドウの外に出ないよう内側へ寄せる。
108	      const rect = targetRef.current?.getBoundingClientRect();
109	      const rawOffsetX = rect ? startX - rect.left : 0;
110	      const rawOffsetY = rect ? startY - rect.top : 0;
111	      dragOffset.current = {
112	        x: Math.min(Math.max(0, rawOffsetX), Math.max(40, layout.width - 60)),
113	        y: Math.min(Math.max(0, rawOffsetY), 40),
114	      };
115	
116	      const moveTo = (clientX: number, clientY: number) => {
117	        setPosition(clientX - dragOffset.current.x, clientY - dragOffset.current.y);
118	      };
119	
120	      const onPointerMove = (ev: PointerEvent) => {
121	        if (!isDraggingHeader.current) return;
122	
123	        if (!getIsFloating()) {
124	          // ドッキング中: 一定距離ドラッグしたら引きはがす
125	          if (Math.hypot(ev.clientX - startX, ev.clientY - startY) > TEAR_OFF_THRESHOLD) {
126	            moveTo(ev.clientX, ev.clientY);
127	            toggleFloating();
128	          }
129	          return;
130	        }
131	
132	        moveTo(ev.clientX, ev.clientY);
133	
134	        const dockRect = getVisibleRect(dockTargetId);
135	        setIsOverDockTarget(!!dockRect && isPointerOverRect(dockRect, ev.clientX, ev.clientY));
136	      };
137	
138	      // pointerup だけでなく pointercancel も拾う。
139	      // これが無いとタッチ操作の中断などでドラッグ状態が解除されず、
140	      // ボタンを離してもウィンドウがカーソルに追従し続ける。
141	      const finishDrag = (ev: PointerEvent) => {
142	        if (!isDraggingHeader.current) return;
143	        isDraggingHeader.current = false;
144	
145	        window.removeEventListener('pointermove', onPointerMove);
146	        window.removeEventListener('pointerup', finishDrag);
147	        window.removeEventListener('pointercancel', finishDrag);
148	
149	        setIsOverDockTarget(false);
150	        if (!getIsFloating()) return;
151	
152	        const dockRect = getVisibleRect(dockTargetId);
153	        if (dockRect && ev.type === 'pointerup' && isPointerOverRect(dockRect, ev.clientX, ev.clientY)) {
154	          toggleFloating();
155	          return;
156	        }
157	
158	        moveTo(ev.clientX, ev.clientY);
159	        setFloatingWindowPosition(id, currentPos.current.x, currentPos.current.y);
160	      };
161	
162	      window.addEventListener('pointermove', onPointerMove);
163	      window.addEventListener('pointerup', finishDrag);
164	      window.addEventListener('pointercancel', finishDrag);
165	    },
166	    [
167	      id,
168	      dockTargetId,
169	      layout.width,
170	      getIsFloating,
171	      toggleFloating,
172	      bringWindowToFront,
173	      setPosition,
174	      setFloatingWindowPosition,
175	      targetRef,
176	      currentPos,
177	    ]
178	  );
179	
180	  /** ウィンドウ本体のスタイル。ドッキング中は何も付けない */
181	  const windowStyle: React.CSSProperties | undefined = isFloating
182	    ? {
183	        position: 'fixed',
184	        top: 0,
185	        left: 0,
186	        zIndex: 50 + Math.max(0, order.indexOf(id)),
187	        width: `${layout.width}px`,
188	        height: `${layout.height}px`,
189	        overflow: contentOverflow,
190	        minWidth: `${minWidth}px`,
191	        minHeight: `${minHeight}px`,
192	        maxWidth: '90vw',
193	        maxHeight: '90vh',
194	      }
195	    : undefined;
196	
197	  /** ウィンドウのどこかを触ったら最前面へ持ち上げる */
198	  const bringToFront = useCallback(() => {
199	    if (isFloating) bringWindowToFront(id);
200	  }, [isFloating, bringWindowToFront, id]);
201	
202	  return {
203	    targetRef,
204	    windowStyle,
205	    handleHeaderPointerDown,
206	    getResizeHandler,
207	    isOverDockTarget,
208	    bringToFront,
209	  };
210	}

