import { encodeTGA, decodeTGA } from '/Users/inouemacmini/Desktop/Kingfisher/src/engine/tga';

const W = 200, H = 160;

// 実際のセルらしい画像を作る: 純白背景 + 黒のアンチエイリアス線で閉じた輪郭
function makeCel(): Uint8ClampedArray {
  const d = new Uint8ClampedArray(W * H * 4);
  for (let i = 0; i < d.length; i += 4) { d[i]=255; d[i+1]=255; d[i+2]=255; d[i+3]=255; }
  const put = (x:number,y:number,v:number)=>{ if(x<0||x>=W||y<0||y>=H)return; const i=(y*W+x)*4; d[i]=v;d[i+1]=v;d[i+2]=v;d[i+3]=255; };
  // 円形の輪郭 (中心線は黒、その外側は中間調＝アンチエイリアス)
  const cx=100, cy=80, r=55;
  for (let a=0; a<3600; a++) {
    const t=(a/3600)*Math.PI*2;
    put(Math.round(cx+Math.cos(t)*r), Math.round(cy+Math.sin(t)*r), 0);
    put(Math.round(cx+Math.cos(t)*(r+1)), Math.round(cy+Math.sin(t)*(r+1)), 128);
    put(Math.round(cx+Math.cos(t)*(r-1)), Math.round(cy+Math.sin(t)*(r-1)), 128);
  }
  return d;
}

// TGA として書き出し → アプリと同じ経路でデコードする
const raw = makeCel();
const buf = encodeTGA({ width: W, height: H, pixelDepth: 32, data: raw });
const img = decodeTGA(buf);

console.log('\n--- デコード結果 ---');
const px = (x:number,y:number)=>{const i=(y*W+x)*4; return {r:img.data[i],g:img.data[i+1],b:img.data[i+2],a:img.data[i+3]};};
console.log('  中心(100,80) 塗る予定の場所 :', JSON.stringify(px(100,80)));
console.log('  線の上(100,25)              :', JSON.stringify(px(100,25)));
console.log('  isReadOnly                  :', (img as any).isReadOnly);

// ストアの初期ツールオプションをそのまま使う
const opts = usePaintStore.getState().toolOptions;
console.log('\n--- ストアの初期ツールオプション ---');
console.log(' ', JSON.stringify(opts));

console.log('\n--- バケツ塗り (中心をクリック) ---');
const before = img.data.slice();
floodFill(img.data, W, H, 100, 80, { r:255,g:0,b:0,a:255 }, opts as any, null);
let changed = 0;
for (let i=0;i<img.data.length;i+=4) if (img.data[i]!==before[i]||img.data[i+1]!==before[i+1]||img.data[i+2]!==before[i+2]) changed++;
console.log(`  変化した画素数: ${changed}`);
console.log(`  中心の色: ${JSON.stringify(px(100,80))}`);
console.log(`  輪郭の外(10,10): ${JSON.stringify(px(10,10))}`);

console.log('\n--- ブラシ描画 ---');
const b2 = img.data.slice();
drawBrushLine(img.data, W, H, 30, 30, 40, 40, opts.brushSize, { r:0,g:0,b:255,a:255 }, false);
let changed2 = 0;
for (let i=0;i<img.data.length;i+=4) if (img.data[i]!==b2[i]||img.data[i+2]!==b2[i+2]) changed2++;
console.log(`  変化した画素数: ${changed2}`);
