  useEffect(() => {
    const clearAll = () => {
      resetDragState('winA');
      resetDragState('winB');
    };
    window.addEventListener('dragend', clearAll);
    window.addEventListener('drop', clearAll);
    return () => {
      window.removeEventListener('dragend', clearAll);
      window.removeEventListener('drop', clearAll);
    };
  }, []);
