        ...state.lightTable,
        items: state.lightTable.items.map((item) =>
          item.id === id ? { ...item, ...transform } : item
        ),
      },
    })),

  toggleLightTableSubItemVisible: (id) =>
    set((state) => ({
      lightTable: {
        ...state.lightTable,
